func:
// Anmeldung.
const cfg = {
    url: env.get('SDI_ODOO_URL') || '',
    db: env.get('SDI_ODOO_DB') || '',
    user: env.get('SDI_ODOO_USER') || '',
    key: env.get('SDI_ODOO_APIKEY') || '',
    aas: env.get('SDI_AAS_URL') || 'http://localhost:8081',
    basis: env.get('SDI_AAS_BASE') || 'localhost/demo/aas'
};
if (!cfg.key) { node.error('Kein Odoo-Schluessel in der Umgebung.'); return null; }
flow.set('cfg', cfg);
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'common', method: 'login', args: [cfg.db, cfg.user, cfg.key] } };
return msg;

// Fetches the variants - order and consumption hang off them, not off the
// product template.
const cfg = flow.get('cfg');
const uid = (msg.payload || {}).result;
if (!uid) { node.error('Login failed'); return null; }
flow.set('uid', uid);
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'product.product', 'search_read',
           [[]], { fields: ['default_code', 'name', 'tracking'], limit: 100 }] } };
return msg;

// Creates a manufacturing order over exactly one piece.
//
// One piece, because a serial number names exactly one piece. The existing
// order over 25 pieces is left untouched - it comes from the sample setup
// and describes a quantity, not an instance.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Odoo reports: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const varianten = (msg.payload || {}).result || [];
flow.set('varianten', varianten);
const ERZEUGNIS = env.get('SDI_ASSEMBLY_ARTICLE') || '000114';
const stift = varianten.find(function (v) { return v.default_code === ERZEUGNIS; });
if (!stift) { node.error('Assembled product ' + ERZEUGNIS + ' not found in Odoo'); return null; }
flow.set('stift', stift);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
// First look whether an open order over one piece is already there.
// Otherwise every call creates another one, and after a few attempts Odoo
// holds orders that never corresponded to a piece.
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'search_read',
           [[['product_id', '=', stift.id], ['product_qty', '=', 1],
             ['state', 'in', ['draft', 'confirmed', 'progress', 'to_close']]]],
           { fields: ['name', 'state'], limit: 1 }] } };
return msg;

// Takes the open order, or creates one.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Finding the order: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const vorhanden = ((msg.payload || {}).result || [])[0];
if (vorhanden) {
    node.warn('Reusing the open order: ' + vorhanden.name);
    flow.set('mo', vorhanden.id);
    return [null, { topic: 'bestaetigt' }];
}
const stift = flow.get('stift');
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'create',
           [{ product_id: stift.id, product_qty: 1 }]] } };
return [msg, null];

// Confirms the order - only then does Odoo keep the consumption lines.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Creating the order: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const mo = (msg.payload || {}).result;
flow.set('mo', mo);
node.warn('Manufacturing order created, id=' + mo);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'action_confirm',
           [[mo]]] } };
return msg;

// Has Odoo produce the serial number of the assembled product.
//
// It is drawn from the number sequence of the article, so it follows the
// pattern that was configured there. Composing it here would be a second
// route beside Odoo's own - and two routes drift apart.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Confirming: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'action_generate_serial',
           [[flow.get('mo')]]] } };
return msg;

// Reads the order with its number and consumption lines.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.warn('Producing the serial number: '
            + ((msg.payload.error.data) || {}).message
            + ' - the order is processed further regardless.');
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'read',
           [[flow.get('mo')],
            ['name', 'state', 'qty_producing', 'lot_producing_ids',
             'move_raw_line_ids']]] } };
return msg;

// Fetches the consumption lines in order to assign serial numbers to them.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Reading the order: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const mo = ((msg.payload || {}).result || [])[0] || {};
flow.set('moDaten', mo);
node.warn('Order ' + mo.name + ' | state ' + mo.state
        + ' | quantity ' + mo.qty_producing
        + ' | numbers ' + JSON.stringify(mo.lot_producing_ids)
        + ' | consumption lines ' + (mo.move_raw_line_ids || []).length);

if (!(mo.move_raw_line_ids || []).length) {
    node.warn('No consumption lines - Odoo creates them once stock '
            + 'is reserved. The linkage then stays incomplete.');
    return [null, { topic: 'aas' }];
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.move.line', 'read',
           [mo.move_raw_line_ids, ['product_id', 'lot_id', 'quantity']]] } };
return [msg, null];

// Shows which components are consumed under which number.
if ((msg.payload || {}).error) {
    node.error('Consumption lines: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const zeilen = (msg.payload || {}).result || [];
flow.set('verbrauch', zeilen);
for (const z of zeilen) {
    node.warn('   consumed: ' + JSON.stringify(z.product_id)
            + ' | quantity ' + z.quantity + ' | number ' + JSON.stringify(z.lot_id));
}
return { topic: 'aas' };

// Fetches the number Odoo gave the assembled product.
//
// The first two blocks of the component numbers come from it: they say
// which pen the part sits in.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
const mo = flow.get('moDaten') || {};
const los = (mo.lot_producing_ids || [])[0];
if (!los) {
    node.warn('The order carries no serial number - components therefore '
            + 'get no complete number.');
    return [null, { topic: 'aas' }];
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.lot', 'read', [[los], ['name']]] } };
return [msg, null];

// Keeps the number of the pen and starts the round over the components.
if ((msg.payload || {}).error) {
    node.error('Reading the number: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const l = ((msg.payload || {}).result || [])[0] || {};
flow.set('stiftNummer', l.name || '');
node.warn('Assembled product carries ' + l.name);
return msg;

// Prepares the numbering for every tracked component.
//
// Only components under serial tracking get one. For purchased parts the
// line stays without a number - that is not an omission but the truth: we
// do not manufacture them.
const varianten = flow.get('varianten') || [];
const verbrauch = flow.get('verbrauch') || [];
const offen = [];
for (const z of verbrauch) {
    const v = varianten.find(function (x) { return x.id === (z.product_id || [])[0]; });
    if (!v || v.tracking !== 'serial') { continue; }
    if ((z.lot_id || [])[0]) { continue; }
    offen.push({ zeile: z.id, artikel: v.default_code, produkt: v.id });
}
flow.set('offen', offen);
flow.set('n', 0);
node.warn('Tracked components still without a number: ' + offen.length);
return { topic: 'naechstes' };

// Fetches the number sequence of the next component.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
const offen = flow.get('offen') || [];
const n = flow.get('n') || 0;
if (n >= offen.length) { return [null, { topic: 'abschliessen' }]; }

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'product.template', 'search_read',
           [[['default_code', '=', offen[n].artikel]]],
           { fields: ['lot_sequence_id'], limit: 1 }] } };
return [msg, null];

// Composes the complete number and creates it.
//
// The component instance comes from the number sequence of the component -
// it counts the pieces manufactured of that kind. The leading blocks come
// from the product being assembled here. Only at assembly are both known.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Number sequence: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const tmpl = ((msg.payload || {}).result || [])[0] || {};
const kreis = tmpl.lot_sequence_id;
const offen = flow.get('offen') || [];
const n = flow.get('n') || 0;
const stiftNummer = flow.get('stiftNummer') || '';
const stiftInstanz = stiftNummer.split('-')[1] || '001';

if (!kreis) {
    node.warn('No number sequence for ' + offen[n].artikel + ' - skipped.');
    flow.set('n', n + 1);
    return [null, { topic: 'naechstes' }];
}
flow.set('kreis', kreis[0]);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'ir.sequence', 'read',
           [[kreis[0]], ['padding', 'number_next_actual']]] } };
return [msg, null];

// Creates the serial number of the component.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Reading the sequence: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const k = ((msg.payload || {}).result || [])[0] || {};
const offen = flow.get('offen') || [];
const n = flow.get('n') || 0;
const ERZEUGNIS = env.get('SDI_ASSEMBLY_ARTICLE') || '000114';
const stiftInstanz = (flow.get('stiftNummer') || '').split('-')[1] || '001';

function stellen(wert, anzahl) {
    let s = String(wert);
    while (s.length < anzahl) { s = '0' + s; }
    return s;
}
const nummer = ERZEUGNIS + '-' + stiftInstanz + '-' + offen[n].artikel + '-'
             + stellen(k.number_next_actual, k.padding || 3);
flow.set('neueNummer', nummer);
flow.set('naechsteZahl', (k.number_next_actual || 1) + 1);
node.warn('   ' + offen[n].artikel + ' gets ' + nummer);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.lot', 'create',
           [{ name: nummer, product_id: offen[n].produkt }]] } };
return msg;

// Traegt die Nummer in die Verbrauchszeile ein.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Nummer anlegen: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const los = (msg.payload || {}).result;
const offen = flow.get('offen') || [];
const n = flow.get('n') || 0;
flow.set('losId', los);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.move.line', 'write',
           [[offen[n].zeile], { lot_id: los }]] } };
return msg;

// Advances the number sequence and moves on to the next component.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.error('Setting the line: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'ir.sequence', 'write',
           [[flow.get('kreis')],
            { number_next_actual: flow.get('naechsteZahl') }]] } };
return msg;

// Naechstes Bauteil.
flow.set('n', (flow.get('n') || 0) + 1);
return { topic: 'naechstes' };

// Closes the order.
//
// Only with this is the piece manufactured and the linkage booked - before
// that it is a declaration of intent. If Odoo refuses to close, because
// stock is missing for instance, that is reported and the flow carries on:
// the assignment is then in the shell, the closing is not, and both are
// visible.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
// With extra entries in the context: otherwise Odoo asks back - too little
// consumed, create a backorder? - and returns a dialog instead of an error.
// The call then looks successful while the order stays open.
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'button_mark_done',
           [[flow.get('mo')]],
           { context: { skip_consumption: true, skip_immediate: true,
                        skip_backorder: true } }] } };
return msg;

// Looks whether the order really is closed.
//
// The return value is no evidence: Odoo answers without an error even when
// it would in truth have opened a dialog. The state is therefore read back.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
if ((msg.payload || {}).error) {
    node.warn('Closing refused: '
            + ((msg.payload.error.data) || {}).message);
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'read',
           [[flow.get('mo')], ['name', 'state']]] } };
return msg;

// Reports the actual state.
const a = (((msg.payload || {}).result) || [])[0] || {};
if (a.state === 'done') {
    node.warn('Order ' + a.name + ' closed.');
} else {
    node.warn('Order ' + a.name + ' stays open (state ' + a.state
            + '). The booking stands, the closing does not - the next run '
            + 'would take the same order again.');
}
return msg;

// Reads the consumption lines once more - now with their numbers.
//
// Earlier the shell went into the write with the state from before the
// assignment and reported "0 components with a number", although three had
// just been given out. What goes into the shell has to come from the
// server, not from the memory of the flow.
const cfg = flow.get('cfg');
const uid = flow.get('uid');
const mo = flow.get('moDaten') || {};
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.move.line', 'read',
           [mo.move_raw_line_ids || [], ['product_id', 'lot_id', 'quantity']]] } };
return msg;

// Takes over the fresh state.
if ((msg.payload || {}).error) {
    node.error('Reading the consumption: ' + ((msg.payload.error.data) || {}).message);
    return null;
}
const zeilen = (msg.payload || {}).result || [];
flow.set('verbrauch', zeilen);
let mitNummer = 0;
for (const z of zeilen) { if ((z.lot_id || [])[0]) { mitNummer = mitNummer + 1; } }
node.warn('Consumption after the assignment: ' + mitNummer + ' of '
        + zeilen.length + ' lines carry a number.');
return msg;

// Records the linkage in the shell of the assembled product.
//
// What is booked gets written - and only that. What Odoo did not confirm is
// not in the shell either; a linkage nobody can produce evidence for would
// be worse than none.
const cfg = flow.get('cfg');
const mo = flow.get('moDaten') || {};
const verbrauch = flow.get('verbrauch') || [];
const varianten = flow.get('varianten') || [];
function artikelVon(id) {
    const v = varianten.find(function (x) { return x.id === id; });
    return v ? v.default_code : '';
}

const eintraege = [];
for (const z of verbrauch) {
    const nummer = (z.lot_id || [])[1] || '';
    if (!nummer) { continue; }
    eintraege.push({ artikel: artikelVon((z.product_id || [])[0]),
                     nummer: nummer, menge: z.quantity });
}
flow.set('verbaut', eintraege);
node.warn('Installed pieces with a number: ' + eintraege.length);

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .split('+').join('-').split('/').join('_').split('=').join('');
}
const PRODUKT = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
flow.set('produktKennung', b64(cfg.basis + '/' + PRODUKT + '/DataSources'));
msg.url = cfg.aas + '/submodels/' + flow.get('produktKennung');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Puts the installed pieces under the ERP data source.
const cfg = flow.get('cfg');
const mo = flow.get('moDaten') || {};
const verbaut = flow.get('verbaut') || [];
const sm = msg.payload;
if (!sm || !sm.submodelElements) {
    node.error('DataSources of the assembled product cannot be read');
    return null;
}
const prop = function (id, v, t) {
    return { modelType: 'Property', idShort: id, valueType: t || 'xs:string',
             value: v === null || v === undefined ? '' : String(v) };
};
const smc = function (id, v) {
    return { modelType: 'SubmodelElementCollection', idShort: id, value: v };
};
// Elements directly inside a list carry no idShort. The specification
// forbids it (AASd-120): in a list the order counts, not the name. With a
// name the package is rejected.
const listenglied = function (v) {
    return { modelType: 'SubmodelElementCollection', value: v };
};
const sml = function (id, v) {
    return { modelType: 'SubmodelElementList', idShort: id,
             typeValueListElement: 'SubmodelElementCollection',
             orderRelevant: false, value: v };
};

let liste = null;
for (const e of sm.submodelElements) {
    if (e.idShort === 'DataSources') { liste = e; }
}
const erp = ((liste || {}).value || []).find(function (e) {
    return e.idShort === 'ERP' || e.idShort === 'ERPData';
});
if (!erp) { node.error('No ERP data source in the shell'); return null; }

const stuecke = verbaut.map(function (v) {
    return listenglied([
        prop('ArticleNumber', v.artikel),
        prop('SerialNumber', v.nummer),
        prop('Quantity', v.menge, 'xs:double')
    ]);
});
const neuWerte = [
    prop('ManufacturingOrder', mo.name || ''),
    // The number of the assembled piece itself. An expression stood here
    // that came out empty in both cases - a field that is always empty
    // catches nobody's eye and makes the entry worthless.
    prop('SerialNumber', flow.get('stiftNummer') || ''),
    prop('TimeOfBooking', new Date().toISOString(), 'xs:dateTime'),
    prop('BookedComponents', String(stuecke.length), 'xs:int'),
    sml('InstalledComponents', stuecke)
];

// A list, not a single entry.
//
// Earlier every booking replaced the previous one - the shell then knew only
// the piece assembled last. A product passport should give information on
// every piece, including the one from the day before yesterday. Only the
// entry with the same number is replaced, so a second run creates no
// duplicate.
let sammlung = (erp.value || []).find(function (x) {
    return x && x.idShort === 'AssemblyRecords';
});
if (!sammlung) {
    sammlung = sml('AssemblyRecords', []);
    erp.value.push(sammlung);
}
// The former single entry moves into the list instead of being lost.
const alt = (erp.value || []).find(function (x) {
    return x && x.idShort === 'AssemblyRecord';
});
if (alt) {
    erp.value = erp.value.filter(function (x) { return x !== alt; });
    const altNummer = (alt.value || []).find(function (y) {
        return y.idShort === 'SerialNumber';
    });
    if (altNummer && altNummer.value
        && altNummer.value !== flow.get('stiftNummer')) {
        delete alt.idShort;
        sammlung.value.push(alt);
    }
}
const neu = listenglied(neuWerte);
sammlung.value = (sammlung.value || []).filter(function (x) {
    const n = (x.value || []).find(function (y) { return y.idShort === 'SerialNumber'; });
    return !(n && n.value === flow.get('stiftNummer'));
});
sammlung.value.push(neu);

msg.url = cfg.aas + '/submodels/' + flow.get('produktKennung');
msg.method = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = sm;
return msg;

// Reports the result.
const mo = flow.get('moDaten') || {};
const verbaut = flow.get('verbaut') || [];
node.warn('Assembly booked: order ' + (mo.name || '?') + ', '
        + verbaut.length + ' components with a number in the shell.');
for (const v of verbaut) { node.warn('   ' + v.artikel + ' ' + v.nummer); }
return null;
